using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Threading;

internal static class PingVerification {
    static void Put(byte[] data,int at,uint value){Buffer.BlockCopy(BitConverter.GetBytes(value),0,data,at,4);}
    static void VerifyLifecycle(){
        var connection=new TcpPingReader.Connection{Row=new byte[20],Family=2};var list=new List<TcpPingReader.Connection>{connection};bool enabled=false,denied=false;uint count=1;int enables=0,disables=0;
        Func<TcpPingReader.Connection,byte[],byte[],uint> read=delegate(TcpPingReader.Connection c,byte[] rw,byte[] rod){rw[0]=(byte)(enabled?1:0);Put(rod,108,150);Put(rod,128,count);return 0;};
        Func<TcpPingReader.Connection,bool,uint> set=delegate(TcpPingReader.Connection c,bool active){if(active){enables++;if(denied)return 5;}else disables++;enabled=active;return 0;};
        using(var reader=new TcpPingReader(delegate{return list;},read,set)){reader.Poll(0);if(reader.Value!=150||enables!=1)throw new Exception("Existing connections must start measuring without reconnecting");reader.Poll(6);if(reader.Value.HasValue)throw new Exception("Unchanged RTT count cannot keep an idle sample fresh");count++;reader.Poll(7);if(reader.Value!=150)throw new Exception("New acknowledgments must recover an expired sample");list.Clear();reader.Poll(9);if(reader.Value.HasValue||disables!=1)throw new Exception("Connection removal must clear reading and release only owned statistics");list.Add(new TcpPingReader.Connection{Row=new byte[20],Family=2});denied=true;reader.Poll(11);if(reader.Status!="Ping measurement needs permission"||reader.Error!=5)throw new Exception("Denied collection must report a permission error");int before=enables;reader.Poll(12);reader.Poll(15);if(reader.Error!=5||enables!=before)throw new Exception("Permission diagnostics must persist during retry backoff");denied=false;count++;reader.Poll(22);if(reader.Value!=150||reader.Error!=0)throw new Exception("Delayed retries must recover after permission becomes available");}
        if(disables!=2)throw new Exception("Disposal must release newly owned collection");enabled=true;enables=disables=0;list[0]=new TcpPingReader.Connection{Row=new byte[20],Family=2};using(var reader=new TcpPingReader(delegate{return list;},read,set)){reader.Poll(0);if(reader.Value!=150)throw new Exception("Pre-enabled collection must be readable");}if(enables!=0||disables!=0||!enabled)throw new Exception("Other applications' pre-enabled TCP statistics must remain untouched");
        var secondary=new TcpPingReader.Connection{Row=new byte[20],Family=2};secondary.Row[4]=1;list.Add(secondary);using(var reader=new TcpPingReader(delegate{return list;},delegate(TcpPingReader.Connection c,byte[] rw,byte[] rod){return c.Row[4]==1?5:read(c,rw,rod);},set)){reader.Poll(0);if(reader.Value!=150||reader.Error!=0||reader.Status!="Measuring server latency")throw new Exception("Secondary connection failures must not override valid selected-server readings");}
    }
    internal static void Run(string root){
        VerifyLifecycle();
        var identity=new TcpPingReader.Connection{Family=2,Row=new byte[20]};string key=identity.Key;for(int n=0;n<10000;n++)if(!object.ReferenceEquals(key,identity.Key))throw new Exception("Polling immutable endpoints must reuse their cached identity");var same=new TcpPingReader.Connection{Family=2,Row=new byte[20]};var other=new TcpPingReader.Connection{Family=23,Row=new byte[52]};if(key!=same.Key||key==other.Key)throw new Exception("Cached identities must preserve exact endpoint and address-family isolation");var changedRow=(byte[])same.Row.Clone();changedRow[4]=1;var different=new TcpPingReader.Connection{Family=2,Row=changedRow};if(different.Key==key)throw new Exception("A new endpoint gets an independent identity");
        var stats=new byte[160];Put(stats,108,153);Put(stats,128,4);
        if(TcpPingReader.Decode(false,stats).HasValue||TcpPingReader.Decode(true,new byte[4]).HasValue||TcpPingReader.Decode(true,stats)!=153)throw new Exception("RTT requires enabled collection, full native struct and samples");
        Put(stats,128,0);if(TcpPingReader.Decode(true,stats).HasValue)throw new Exception("No samples must not invent ping");Put(stats,128,1);Put(stats,108,uint.MaxValue);if(TcpPingReader.Decode(true,stats).HasValue)throw new Exception("Uninitialized RTT must be ignored");Put(stats,108,0);if(TcpPingReader.Decode(true,stats)!=0)throw new Exception("A measured sub-ms RTT rounded to zero is valid");
        var pids=new HashSet<int>{42};var table=new byte[4+3*24];Put(table,0,3);for(int n=0;n<3;n++){int at=4+n*24;Put(table,at,5);Put(table,at+20,(uint)(n==2?84:42));table[at+16]=0x34;table[at+17]=0x10;}table[4+24+16]=1;
        var rows=TcpPingReader.ParseTable(table,2,pids);if(rows.Count!=1||rows[0].Row.Length!=20||BitConverter.ToUInt32(rows[0].Row,0)!=5)throw new Exception("IPv4 discovery must isolate established game-port connections owned by AION2");
        var six=new byte[60];Put(six,0,1);six[4+15]=1;six[4+24+15]=2;Put(six,4+16,7);Put(six,4+40,8);six[4+44]=0x34;six[4+45]=0x10;Put(six,4+48,5);Put(six,4+52,42);
        rows=TcpPingReader.ParseTable(six,23,pids);if(rows.Count!=1||rows[0].Row.Length!=52||BitConverter.ToUInt32(rows[0].Row,0)!=5||rows[0].Row[19]!=1||rows[0].Row[43]!=2||BitConverter.ToUInt32(rows[0].Row,20)!=7||BitConverter.ToUInt32(rows[0].Row,44)!=8)throw new Exception("IPv6 owner table must map to native TCP6ROW: state first, addresses and scope preserved");
        Put(six,4+48,2);if(TcpPingReader.ParseTable(six,23,pids).Count!=0)throw new Exception("Listeners cannot be ping targets");bool rejected=false;Put(table,0,99);try{TcpPingReader.ParseTable(table,2,pids);}catch(IOException){rejected=true;}if(!rejected)throw new Exception("Truncated native table must be rejected");
        var sample=new TcpPingReader.Connection{Value=150,FreshAt=10};if(!TcpPingReader.Fresh(sample,15)||TcpPingReader.Fresh(sample,15.001))throw new Exception("Old RTT must expire even if the connection still exists");
        var serial=new System.Web.Script.Serialization.JavaScriptSerializer();var o=FpsOptions.PingDefaults();o.Enabled=true;o.RefreshIntervalMs=5000;o.Color="#123456";var restored=FpsOptions.Read(serial.Deserialize<Dictionary<string,object>>(serial.Serialize(new{ping=o})),"ping");if(!FpsOptions.Same(o,restored)||FpsOptions.Read(new Dictionary<string,object>(),"ping").Enabled||FpsOptions.Read(new Dictionary<string,object>(),"ping").RefreshIntervalMs!=1000)throw new Exception("Independent ping settings and safe migration");
        using(var monitor=new PingMonitor()){if(monitor.Value.HasValue||monitor.Status!="Ping disabled")throw new Exception("Disabled ping must not invent readings");monitor.Configure(false,500);var thread=typeof(PingMonitor).GetField("thread",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(monitor);if(thread!=null)throw new Exception("Disabled ping must not start a worker");}
        using(var owner=new EnergyOverlay(root,true)){using(var widget=new FpsOverlay(owner,root,true,true))widget.VerifyCache();var pane=new FpsSettingsPane(owner,new System.Windows.Window(),true);pane.Verify();}
        File.WriteAllText(Path.Combine(root,"ping-test.txt"),"PASS: native RTT validity, disabled/no samples/uninitialized/stale guards; IPv4/IPv6 PID+port+established discovery, scope and row mapping, malformed bounds; independent persisted options/defaults, disabled zero worker; ping controls/history, shared crisp renderer and bounded resource cache.");
    }
    internal static int Live(string root){var output=new System.Text.StringBuilder();int samples=0;using(var monitor=new PingMonitor()){monitor.Configure(true,1000);var clock=Stopwatch.StartNew();using(var process=Process.GetCurrentProcess()){double cpu=process.TotalProcessorTime.TotalMilliseconds;while(clock.Elapsed.TotalSeconds<15){if(monitor.Value.HasValue)samples++;output.AppendLine(clock.Elapsed.TotalSeconds.ToString("F1",System.Globalization.CultureInfo.InvariantCulture)+" | "+monitor.Status+" | "+(monitor.Value.HasValue?monitor.Value.Value.ToString():"unknown"));Thread.Sleep(1000);}process.Refresh();output.AppendLine("CPU ms: "+(process.TotalProcessorTime.TotalMilliseconds-cpu)+"; working set bytes: "+process.WorkingSet64);output.AppendLine(monitor.Diagnostics);}monitor.Configure(false,1000);Thread.Sleep(200);if(monitor.Value.HasValue||monitor.Status!="Ping disabled")throw new Exception("Disable must clear readings immediately");}
        File.WriteAllText(Path.Combine(root,"ping-live-test.txt"),(samples>0?"PASS: real Aion TCP RTT samples: "+samples:"NO DATA: live validation pending")+Environment.NewLine+output);return samples>0?0:1;
    }
}
